public class BankAccount {
    public static void main(String[] args) {
        // a) Define the BankAccount class with instance variables
        class BankAccount {
            String ownerName;
            double balance = 0.0;

            // b) Implement getter and setter methods
            String getOwnerName() {
                return ownerName;
            }

            void setOwnerName(String ownerName) {
                this.ownerName = ownerName;
            }

            double getBalance() {
                return balance;
            }

            // c) Implement constructors
            BankAccount(String ownerName) {
                this.ownerName = ownerName;
            }

            BankAccount() {
                this.ownerName = "Unknown";
            }

            // d) Implement deposit and withdraw methods
            String deposit(double amount) {
                if (amount > 0) {
                    balance += amount;
                    return "Your current balance is €" + String.format("%.1f", balance);
                } else {
                    return "The amount must be greater than zero.";
                }
            }

            String withdraw(double amount) {
                if (amount > 0 && balance >= amount) {
                    balance -= amount;
                    return "Your current balance is €" + String.format("%.1f", balance);
                } else {
                    return "You have insufficient funds.";
                }
            }
        }

        // Create an instance of BankAccount with ownerName "John Doe"
        BankAccount account = new BankAccount("John Doe");

        // Deposit an amount of €100.0
        String depositMessage = account.deposit(100.0);

        // Withdraw an amount of €50.0
        String withdrawMessage = account.withdraw(50.0);

        // Print the deposit and withdraw messages
        System.out.println(depositMessage);
        System.out.println(withdrawMessage);
    }
}
